class calculator:
    """Vector-to-vector operations usable without an instance."""

    @staticmethod
    def dotproduct(V1, V2):
        """Print the dot product of V1 and V2."""
        result = sum(x * y for x, y in zip(V1, V2))
        print(f'Dot product is: {result}')

    @staticmethod
    def add_vec(V1, V2):
        """Print the elementwise sum of V1 and V2."""
        result = [float(x + y) for x, y in zip(V1, V2)]
        print(f'Add Vector is : {result}')

    @staticmethod
    def sous_vec(V1, V2):
        """Print the elementwise difference of V1 and V2."""
        result = [float(x - y) for x, y in zip(V1, V2)]
        print(f'Sous Vector is: {result}')
